224	// releaseRun cancels the run's context (releasing it) and forgets its channel.
225	func (pm *PathModel) releaseRun() {
226		if pm.cancel != nil {
227			pm.cancel()
228			pm.cancel = nil
229		}
230		pm.msgs = nil
231	}
232	
233	func isPathNavKey(key string) bool {
234		switch key {
235		case "up", "down", "pgup", "pgdown", "home", "end":
236			return true
237		}
238		return false
239	}
240	
241	func (pm *PathModel) handleKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
242		key := msg.String()
243		if pm.pickerOpen() {
244			return pm.handlePickerKey(key)
245		}
246		if key == pathSourceKey {
247			return pm.openPicker()
248		}
249		if isPathNavKey(key) {
250			return pm, pm.table.Update(msg)
251		}
252		if pm.state == pathRunning {
253			if key == "esc" {
254				return pm.cancelRun()
255			}
256			return pm, nil
257		}
258		if key == "enter" {
259			return pm.launch(pm.target)
260		}
261		return pm, nil
262	}
263	
264	// launch starts a run: the model changes here, in Update; the Cmd only does I/O.
265	func (pm *PathModel) launch(tg pathTarget) (*PathModel, tea.Cmd) {
266		if tg.Host == "" {
267			return pm, nil // nothing to trace
268		}
269		if a := pm.launchable(); !a.Enabled() {
270			return pm, pm.footer.Warn(a.Reason)
271		}
272		pm.releaseRun()
273		pm.gen++
274		pm.target = tg
275		pm.clearRun()
276		pm.footer.Clear()
277	
278		ctx, cancel := context.WithCancel(context.Background())
279		ch := make(chan tea.Msg, pathChanCap)
280		pm.cancel, pm.msgs = cancel, ch
281		pm.state = pathRunning
282		return pm, startPathRun(ctx, pm.gen, tg, pm.source, pm.resolveTimeout, pm.engine, ch)
283	}
284	
285	// cancelRun answers esc at once: the run's late messages are dropped by the
286	// generation bump, the hops already seen stay on screen.
287	func (pm *PathModel) cancelRun() (*PathModel, tea.Cmd) {
288		pm.releaseRun()
289		pm.gen++
290		pm.result = &nettrace.Result{Outcome: nettrace.OutcomeCancelled}
291		pm.state = pathDone
292		return pm, nil
293	}
294	
295	// startPathRun builds the launch Cmd from values only, so that no closure
296	// reads the model (Rule 110).
297	func startPathRun(ctx context.Context, gen int, tg pathTarget, src pathSource, timeout time.Duration, e pathEngine, ch chan tea.Msg) tea.Cmd {
298		return tea.Batch(
299			func() tea.Msg {
300				producePath(ctx, gen, tg, src, timeout, e, ch)
301				return nil
302			},
303			waitForPathMsg(ch),
304		)
305	}
