// restoreFormFocus puts the cursor back where focusedField says it is, so only
// that field blinks.
func (m *Model) restoreFormFocus() {
	for _, in := range []*textinput.Model{&m.targetInput, &m.portInput, &m.dnsServerInput} {
		in.Blur()
	}
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

// traceTitle is "Network › Path › host", the host cut with an ellipsis so the
// line never outgrows the frame.
func (m *Model) traceTitle(base string) string {
	host := m.pathModel.target.Host
	if m.width > 0 {
		avail := m.width - traceTitleMargin - ansi.StringWidth(base+traceTitleTrail)
		host = ansi.Truncate(host, max(avail, 1), "…")
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

func (m *Model) moveFocus(delta int) {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

	m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount

	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

func (m *Model) updateActiveInput(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.focusedField {
	case fieldTarget:
		m.targetInput, cmd = m.targetInput.Update(msg)
		m.revalidateTrace()
	case fieldPort:
		m.portInput, cmd = m.portInput.Update(msg)
	case fieldDNSServer:
		m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
	}
	return m, cmd
}

func (m *Model) handleKeyResults(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openDetails()
	case "esc":
		// No origin view means netdiag was opened directly (the command
		// line), so esc stays inside it and resets to the form, as it
		// always has. An origin means it was opened prefilled from
		// elsewhere (status's H, §3.66), and esc returns there instead.
		if m.OriginView == "" {
			return m.resetToForm()
